static void queue_to_d1(void){unsigned i;group("actual12A68 borrowed queue record routes mode1 ID401 through internal15048 to139E6");receive_fresh();queue_record();CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_RETURNED);CHECK(m.receive.memory==&m.memory&&m.receive.consumed==1&&m.receive.d1_calls==1);CHECK(csr_clears==1&&csr_sets==1&&get(A(0xc034),2)==0);CHECK(m.reports.argument==0&&m.reports.command==0xd1&&m.reports.replies==1);CHECK(m.ota.reply_length==8&&m.replies_committed==1);for(i=0;i<8;i++)CHECK(m.ota.reply_data[i]==0x31+i&&m.ota.reply_mask[i]==255);CHECK(m.unresolved==0&&!m.halted);}
