static void oversized_live_reply(void){cr_arguments a;unsigned i;uint32_t before=0,after=0;group("live debug DLC255 yields length257; bounded host view preserves TX prefix without heap allocation");receive_fresh();put(A(0xc795),2,1);put(A(0xc600),0x401,2);put(A(0xc602),8,1);for(i=0;i<8;i++)put(A(0xc603)+i,0x51+i,1);put(A(0xc60b),0,1);live_dlc=1;memset(&a,0,sizeof(a));a.record.kind=CR_RAM;a.record.address=A(0xc600);CHECK(rc_heap_free_sum(&adapter,&before)==1);CHECK(ta_dispatch_receive(&m,CR_DEBUG,&a)==CR_HALT);CHECK(m.ota.reply_length==257&&m.receive.debug_replies==1);CHECK(m.replies_committed==0&&m.ota.interpretation_halted&&m.halted);CHECK(rc_heap_free_sum(&adapter,&after)==1&&after==before);CHECK(m.reply_source_data==NULL&&m.reply_source_known==NULL);}
static void activation_choice(void){uint32_t command_count;group("known CSR transfer preserves queue and suppresses suffix until explicit host activation choice");receive_fresh();queue_record();csr_transfer=1;CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_TRANSFER);CHECK(csr_clears==1&&csr_sets==0&&m.receive.consumed==0&&get(A(0xc034),2)==0x401);CHECK(m.transferred&&m.ota.transferred&&m.unresolved==0&&m.ota.outcome==TC_TRANSFERRED);command_count=m.ota.command_count;CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_TRANSFER&&csr_clears==1&&m.ota.command_count==command_count);CHECK(ta_resume_activation(&m)==1);CHECK(get(A(0xc034),2)==0x401&&!m.transferred&&!m.ota.transferred&&!m.halted);csr_transfer=0;CHECK(ta_dispatch_receive(&m,CR_QUEUE,NULL)==CR_RETURNED&&m.receive.consumed==1&&m.replies_committed==1);}
int main(int argc,char**argv){FILE*f;unsigned i;if(argc!=3)return 2;f=fopen(argv[1],"rb");if(!f||fread(runtime,1,sizeof(runtime),f)!=sizeof(runtime)){if(f)fclose(f);return 2;}fclose(f);f=fopen(argv[2],"rb");if(!f||fread(boot,1,sizeof(boot),f)!=sizeof(boot)){if(f)fclose(f);return 2;}fclose(f);for(i=0;i<14;i++){uid[i]=(uint8_t)(17+i);known[i]=255;}uid[12]=uid[0];uid[13]=uid[1];queue_to_d1();borrowed_live();short_view();debug_consumes();oversized_live_reply();activation_choice();printf("RECEIVE_INTEGRATION_RESULT groups=%u checks=%u failures=%u original_executed=no hardware=no\n",groups,checks,failures);return failures?1:0;}
